<?php ui_header('Mạng lưới','Quản lý kết nối nghề nghiệp và mở rộng network của bạn.'); ?>
<div class="network-layout section"><section><h2><?= ui_icon('users',20) ?> Gợi ý kết nối</h2><div class="panel suggestion-list"><?php foreach(array_slice($suggestions,0,8) as $person): ?><article class="suggestion-row"><div class="person-identity"><?= ui_avatar($person['profile']??[],48) ?><div><strong><?= e($person['profile']['fullName']??$person['email']) ?></strong><p class="muted"><?= e($person['profile']['headline']??'Professional') ?></p></div></div><button class="ghost" data-action="/social/connections" data-body="<?= e(json_encode(['addresseeId'=>$person['id']])) ?>" data-reload>Kết nối</button></article><?php endforeach; if(!$suggestions): ?><div class="empty">Chưa có gợi ý mới.</div><?php endif; ?></div></section>
<section><div class="section-title"><h2><?= ui_icon('users',20) ?> Kết nối của tôi <span class="badge"><?= count($data) ?></span></h2><?php if($data): ?><input id="network-search" placeholder="Tìm kiếm kết nối..." aria-label="Tìm kiếm kết nối"><?php endif; ?></div><div class="network-connections"><?php foreach($data as $c): $isRequester=$c['requesterId']===$user['id'];$other=$isRequester?$c['addressee']:$c['requester']; ?><article class="panel connection-card" data-network-person="<?= e($other['profile']['fullName']??'') ?>"><div class="person-identity"><?= ui_avatar($other['profile']??[],48) ?><div><strong><?= e($other['profile']['fullName']??'Member') ?></strong><p class="muted"><?= e($other['profile']['headline']??'Professional') ?></p><span class="status-badge status-<?= e($c['status']) ?>"><?= e(['PENDING'=>'Đang chờ','ACCEPTED'=>'Đã kết nối','BLOCKED'=>'Đã chặn'][$c['status']]??$c['status']) ?></span></div></div><div class="connection-actions">
<?php if($c['status']==='PENDING'&&!$isRequester): ?><button data-action="/social/connections/<?= e($c['id']) ?>/status" data-method="PATCH" data-body='{"status":"ACCEPTED"}' data-reload>Chấp nhận</button><button class="ghost" data-action="/social/connections/<?= e($c['id']) ?>/status" data-method="PATCH" data-body='{"status":"BLOCKED"}' data-reload>Từ chối</button>
<?php elseif($c['status']==='PENDING'): ?><span class="muted">Đã gửi lời mời</span><button class="ghost" data-action="/social/connections/<?= e($c['id']) ?>" data-method="DELETE" data-reload>Thu hồi</button>
<?php elseif($c['status']==='ACCEPTED'): ?><button class="ghost" data-action="/messages/conversations" data-body="<?= e(json_encode(['participantIds'=>[$other['id']]])) ?>" data-redirect="/messages"><?= ui_icon('message',16) ?> Nhắn tin</button><button class="ghost" data-action="/social/connections/<?= e($c['id']) ?>" data-method="DELETE" data-reload aria-label="Gỡ kết nối"><?= ui_icon('close',16) ?></button>
<?php else: ?><button class="ghost" data-action="/social/connections/<?= e($c['id']) ?>" data-method="DELETE" data-reload>Bỏ chặn</button><?php endif; ?></div></article><?php endforeach; ?></div><?php if(!$data): ?><div class="panel empty"><?= ui_icon('users',32) ?><h2>Chưa có kết nối</h2><p class="muted">Kết nối sẽ hiển thị khi bạn gửi hoặc nhận lời mời.</p></div><?php endif; ?><p id="network-no-results" class="panel empty" hidden>Không tìm thấy kết nối nào phù hợp.</p></section></div>